ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| case {
    ImageFileName=/vssadmin\.exe$/i regex("(?i)delete shadows|resize shadowstorage", field=CommandLine) | Action := "ShadowDelete";
    ImageFileName=/wmic\.exe$/i regex("(?i)shadowcopy delete", field=CommandLine) | Action := "ShadowDelete";
    ImageFileName=/wbadmin\.exe$/i regex("(?i)delete catalog|delete backup|delete systemstatebackup", field=CommandLine) | Action := "BackupDelete";
    ImageFileName=/bcdedit\.exe$/i regex("(?i)recoveryenabled no|bootstatuspolicy ignoreallfailures", field=CommandLine) | Action := "BootRecoveryDisable";
    ImageFileName=/(net|net1|sc)\.exe$/i regex("(?i)stop.*(Veeam|BackupExec|MSSQLSERVER|SQLAgent|Acronis|MSExchange|CrowdStrike|SentinelOne|Sense|WinDefend)", field=CommandLine) | Action := "ServiceKill";
    * | Action := ""
  }
| Action != ""
| groupBy([aid, ComputerName, UserName, bucket(span=5m)], function=[count(as=Total), collect([Action, CommandLine], multival=true)])
| DistinctActions := length(Action)
| DistinctActions >= 3
